  const parseTimecode=value=>{const raw=String(value||'').trim();if(!raw)return 0;if(/^\d+$/.test(raw))return Number(raw);const parts=raw.split(':');if(parts.length>3||parts.some(x=>!/^[0-9]{1,2}$/.test(x)))return NaN;const nums=parts.map(Number);while(nums.length<3)nums.unshift(0);const [h,m,sec]=nums;if(m>59||sec>59)return NaN;return h*3600+m*60+sec};
